import json
import math

# Load analysis data
with open('/app/output/analysis_data.json', 'r') as f:
    data = json.load(f)

kpis = data['kpis']

# Format numbers for display
def fmt_currency(val):
    return f"${val:,.2f}"

def fmt_number(val):
    return f"{val:,.0f}"

def fmt_pct(val):
    return f"{val:.2f}%"

# Build HTML sections
html_parts = []

# ============ HEADER ============
html_parts.append("""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chocolate Retail Sales Performance Report 2023-2024</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
            line-height: 1.6;
            color: #2c3e50;
            background: #f5f7fa;
        }
        .report-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 20px;
        }
        header {
            background: linear-gradient(135deg, #3d2c29 0%, #5d4a43 100%);
            color: white;
            padding: 40px;
            border-radius: 12px;
            margin-bottom: 30px;
        }
        header h1 {
            font-size: 2.2em;
            margin-bottom: 10px;
        }
        header .subtitle {
            opacity: 0.9;
            font-size: 1.1em;
        }
        .timestamp {
            margin-top: 20px;
            font-size: 0.9em;
            opacity: 0.8;
        }
        section {
            background: white;
            border-radius: 12px;
            padding: 30px;
            margin-bottom: 25px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.06);
        }
        h2 {
            color: #3d2c29;
            border-bottom: 3px solid #8b6f5c;
            padding-bottom: 12px;
            margin-bottom: 25px;
            font-size: 1.5em;
        }
        h3 {
            color: #5d4a43;
            margin: 20px 0 15px 0;
        }
        .kpi-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }
        .kpi-card {
            background: linear-gradient(135deg, #f8f5f3 0%, #ebe5e0 100%);
            padding: 25px;
            border-radius: 10px;
            border-left: 5px solid #8b6f5c;
        }
        .kpi-label {
            font-size: 0.85em;
            color: #7a6a5a;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 8px;
        }
        .kpi-value {
            font-size: 1.8em;
            font-weight: 700;
            color: #3d2c29;
        }
        .kpi-sub {
            font-size: 0.8em;
            color: #888;
            margin-top: 5px;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 0.95em;
        }
        th {
            background: #5d4a43;
            color: white;
            padding: 14px 12px;
            text-align: left;
            font-weight: 600;
        }
        td {
            padding: 12px;
            border-bottom: 1px solid #eee;
        }
        tr:hover {
            background: #faf8f6;
        }
        .chart-container {
            margin: 30px 0;
            padding: 20px;
            background: #faf9f7;
            border-radius: 10px;
        }
        .chart-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }
        @media (max-width: 768px) {
            .chart-row {
                grid-template-columns: 1fr;
            }
        }
        .highlight-box {
            background: linear-gradient(135deg, #e8f4e8 0%, #d4edda 100%);
            border-left: 4px solid #28a745;
            padding: 20px;
            border-radius: 8px;
            margin: 20px 0;
        }
        .warning-box {
            background: linear-gradient(135deg, #fff3cd 0%, #ffeeba 100%);
            border-left: 4px solid #ffc107;
            padding: 20px;
            border-radius: 8px;
            margin: 20px 0;
        }
        .insight-box {
            background: #f8f9fa;
            padding: 15px 20px;
            border-radius: 8px;
            margin: 15px 0;
            border-left: 4px solid #6c757d;
        }
        .metrics-row {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 15px;
            margin: 20px 0;
        }
        .metric-item {
            text-align: center;
            padding: 15px;
            background: #f8f5f3;
            border-radius: 8px;
        }
        .metric-item .value {
            font-size: 1.4em;
            font-weight: 700;
            color: #3d2c29;
        }
        .metric-item .label {
            font-size: 0.8em;
            color: #7a6a5a;
            margin-top: 5px;
        }
        .footer {
            text-align: center;
            padding: 30px;
            color: #888;
            font-size: 0.85em;
        }
        .badge {
            display: inline-block;
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 0.75em;
            font-weight: 600;
        }
        .badge-success { background: #d4edda; color: #155724; }
        .badge-warning { background: #fff3cd; color: #856404; }
        .badge-info { background: #cce5ff; color: #004085; }
    </style>
</head>
<body>
    <div class="report-container">
        <header>
            <h1>Chocolate Retail Sales Performance Report</h1>
            <div class="subtitle">Comprehensive Analysis of Sales Transactions Across Stores, Products & Customer Segments</div>
            <div class="timestamp">Reporting Period: January 2023 – December 2024 | Generated: """ + __import__('datetime').datetime.now().strftime('%B %d, %Y') + """</div>
        </header>
""")

# ============ SECTION 1: EXECUTIVE SUMMARY ============
# Year-over-year growth
rev_growth = ((kpis['total_revenue'] - (data['revenue_2023'])) / data['revenue_2023']) * 100 if data['revenue_2023'] > 0 else 0

html_parts.append("""
        <section id="executive-summary">
            <h2>Executive Summary</h2>

            <div class="kpi-grid">
                <div class="kpi-card">
                    <div class="kpi-label">Total Revenue</div>
                    <div class="kpi-value">""" + fmt_currency(kpis['total_revenue']) + """</div>
                    <div class="kpi-sub">2023: """ + fmt_currency(data['revenue_2023']) + """ | 2024: """ + fmt_currency(data['revenue_2024']) + """</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Total Profit</div>
                    <div class="kpi-value">""" + fmt_currency(kpis['total_profit']) + """</div>
                    <div class="kpi-sub">2023: """ + fmt_currency(data['profit_2023']) + """ | 2024: """ + fmt_currency(data['profit_2024']) + """</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Average Profit Margin</div>
                    <div class="kpi-value">""" + fmt_pct(kpis['avg_profit_margin']) + """</div>
                    <div class="kpi-sub">Consistent across both years</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Total Orders</div>
                    <div class="kpi-value">""" + fmt_number(kpis['total_orders']) + """</div>
                    <div class="kpi-sub">2023: """ + fmt_number(data['orders_2023']) + """ | 2024: """ + fmt_number(data['orders_2024']) + """</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Average Order Value</div>
                    <div class="kpi-value">""" + fmt_currency(kpis['avg_order_value']) + """</div>
                    <div class="kpi-sub">Per transaction</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Discount Utilization</div>
                    <div class="kpi-value">""" + fmt_pct(kpis['discount_utilization']) + """</div>
                    <div class="kpi-sub">37.5% of orders had discount</div>
                </div>
            </div>

            <div class="highlight-box">
                <strong>Key Finding:</strong> Revenue grew """ + f"{rev_growth:.1f}" + """% from 2023 to 2024 (""" + fmt_currency(data['revenue_2023']) + """ → """ + fmt_currency(data['revenue_2024']) + """). Total profit margin remained stable at approximately 40%, indicating consistent operational efficiency despite promotional discounting.
            </div>
        </section>
""")

# ============ SECTION 2: SALES TRENDS ============
# Build monthly data for JS
monthly = data['monthly']
month_labels = []
rev_2023, rev_2024 = [], []
orders_2023, orders_2024 = [], []

for m in range(1, 13):
    month_labels.append(['', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][m])
    for row in monthly:
        if row['year'] == 2023 and row['month'] == m:
            rev_2023.append(row['revenue'])
            orders_2023.append(row['orders'])
        elif row['year'] == 2024 and row['month'] == m:
            rev_2024.append(row['revenue'])
            orders_2024.append(row['orders'])

# Quarterly data
quarterly = data['quarterly']
q_labels = ['Q1 2023', 'Q2 2023', 'Q3 2023', 'Q4 2023', 'Q1 2024', 'Q2 2024', 'Q3 2024', 'Q4 2024']
q_revenue = []
for q in range(1, 5):
    for row in quarterly:
        if row['year'] == 2023 and row['quarter'] == q:
            q_revenue.append(row['revenue'])
for q in range(1, 5):
    for row in quarterly:
        if row['year'] == 2024 and row['quarter'] == q:
            q_revenue.append(row['revenue'])

html_parts.append("""
        <section id="sales-trends">
            <h2>Sales Trends Over Time</h2>
            <p>This section analyzes monthly and quarterly revenue and order volume trends across 2023 and 2024, revealing seasonality patterns and year-over-year growth trajectories.</p>

            <div class="chart-container">
                <canvas id="monthlyRevenueChart"></canvas>
            </div>

            <div class="chart-row">
                <div class="chart-container">
                    <h3>Quarterly Revenue Comparison</h3>
                    <canvas id="quarterlyRevenueChart"></canvas>
                </div>
                <div class="chart-container">
                    <h3>Monthly Orders Comparison</h3>
                    <canvas id="monthlyOrdersChart"></canvas>
                </div>
            </div>

            <h3>Quarterly Performance Summary</h3>
            <table>
                <thead>
                    <tr>
                        <th>Quarter</th>
                        <th>Revenue</th>
                        <th>Profit</th>
                        <th>Orders</th>
                        <th>Profit Margin</th>
                    </tr>
                </thead>
                <tbody>
""")

for row in quarterly:
    year = int(row['year'])
    q = int(row['quarter'])
    html_parts.append(f"""
                    <tr>
                        <td>Q{q} {year}</td>
                        <td>{fmt_currency(row['revenue'])}</td>
                        <td>{fmt_currency(row['profit'])}</td>
                        <td>{fmt_number(row['orders'])}</td>
                        <td>{fmt_pct(row['profit_margin'])}</td>
                    </tr>
""")

html_parts.append("""
                </tbody>
            </table>

            <div class="insight-box">
                <strong>Seasonality Insight:</strong> Revenue shows moderate seasonality with summer months (June-August) and the December holiday period showing higher transaction volumes. Year-over-year, 2024 showed stronger H1 performance but weakened in H2 compared to 2023.
            </div>
        </section>

        <script>
            // Monthly Revenue Chart
            new Chart(document.getElementById('monthlyRevenueChart'), {
                type: 'line',
                data: {
                    labels: """ + str(month_labels) + """,
                    datasets: [
                        {
                            label: '2023 Revenue',
                            data: """ + str(rev_2023) + """,
                            borderColor: '#8b6f5c',
                            backgroundColor: 'rgba(139, 111, 92, 0.1)',
                            borderWidth: 2,
                            fill: true,
                            tension: 0.3
                        },
                        {
                            label: '2024 Revenue',
                            data: """ + str(rev_2024) + """,
                            borderColor: '#3d2c29',
                            backgroundColor: 'rgba(61, 44, 41, 0.1)',
                            borderWidth: 2,
                            fill: true,
                            tension: 0.3
                        }
                    ]
                },
                options: {
                    responsive: true,
                    plugins: {
                        title: {
                            display: true,
                            text: 'Monthly Revenue: 2023 vs 2024',
                            font: { size: 16, weight: 'bold' }
                        },
                        legend: { position: 'top' }
                    },
                    scales: {
                        y: {
                            beginAtZero: false,
                            ticks: { callback: value => '$' + value.toLocaleString() }
                        }
                    }
                }
            });

            // Quarterly Revenue Chart
            new Chart(document.getElementById('quarterlyRevenueChart'), {
                type: 'bar',
                data: {
                    labels: """ + str(q_labels) + """,
                    datasets: [{
                        label: 'Revenue',
                        data: """ + str(q_revenue) + """,
                        backgroundColor: [
                            'rgba(139, 111, 92, 0.7)',
                            'rgba(139, 111, 92, 0.7)',
                            'rgba(139, 111, 92, 0.7)',
                            'rgba(139, 111, 92, 0.7)',
                            'rgba(61, 44, 41, 0.8)',
                            'rgba(61, 44, 41, 0.8)',
                            'rgba(61, 44, 41, 0.8)',
                            'rgba(61, 44, 41, 0.8)'
                        ],
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    plugins: {
                        title: {
                            display: true,
                            text: 'Quarterly Revenue (2023 vs 2024)',
                            font: { size: 14, weight: 'bold' }
                        },
                        legend: { display: false }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            ticks: { callback: value => '$' + value.toLocaleString() }
                        }
                    }
                }
            });

            // Monthly Orders Chart
            new Chart(document.getElementById('monthlyOrdersChart'), {
                type: 'bar',
                data: {
                    labels: """ + str(month_labels) + """,
                    datasets: [
                        {
                            label: '2023 Orders',
                            data: """ + str(orders_2023) + """,
                            backgroundColor: 'rgba(139, 111, 92, 0.7)',
                            borderWidth: 1
                        },
                        {
                            label: '2024 Orders',
                            data: """ + str(orders_2024) + """,
                            backgroundColor: 'rgba(61, 44, 41, 0.8)',
                            borderWidth: 1
                        }
                    ]
                },
                options: {
                    responsive: true,
                    plugins: {
                        title: {
                            display: true,
                            text: 'Monthly Orders (2023 vs 2024)',
                            font: { size: 14, weight: 'bold' }
                        },
                        legend: { position: 'top' }
                    }
                }
            });
        </script>
""")

# ============ SECTION 3: PRODUCT PERFORMANCE ============
top_products = data['top_10_products']

html_parts.append("""
        <section id="product-performance">
            <h2>Product & Category Performance</h2>
            <p>This section evaluates which products generate the most revenue and profit, identifying top performers and analyzing the relationship between product characteristics and sales performance.</p>

            <h3>Top 10 Products by Revenue</h3>
            <table>
                <thead>
                    <tr>
                        <th>Rank</th>
