                        <th>Revenue</th>
                        <th>Profit</th>
                        <th>Orders</th>
                        <th>Units Sold</th>
                        <th>Margin</th>
                    </tr>
                </thead>
                <tbody>
""")

for i, row in enumerate(top_products, 1):
    html_parts.append(f"""
                    <tr>
                        <td>{i}</td>
                        <td><strong>{row['product_id']}</strong></td>
                        <td>{fmt_currency(row['revenue'])}</td>
                        <td>{fmt_currency(row['profit'])}</td>
                        <td>{fmt_number(row['orders'])}</td>
                        <td>{fmt_number(row['quantity'])}</td>
