            </div>
        </section>

        <script>
            new Chart(document.getElementById('productRevenueChart'), {
                type: 'bar',
                data: {
                    labels: """ + str([p['product_id'] for p in top_products]) + """,
                    datasets: [{
                        label: 'Revenue',
                        data: """ + str([p['revenue'] for p in top_products]) + """,
                        backgroundColor: 'rgba(139, 111, 92, 0.8)',
                        borderColor: '#5d4a43',
